messages.content:
Tool response:
Tool: create_custom_attribute_for_asset_type
Description: Create Custom Attribute For Asset Type
Parameters:
    {
      "type": "object",
      "properties": {
        "asset_type_id": {
          "type": "integer",
          "description": "Internal ID of the asset type to add the custom attribute to",
          "title": "Asset Type Id"
        },
        "name": {
          "type": "string",
          "title": "Name",
          "description": "Name of the custom attribute"
        },
        "data_type": {
          "type": "string",
          "title": "Data Type",
          "description": "Data type of the custom attribute (must be INTEGER)"
        },
        "is_required": {
          "type": "boolean",
          "title": "Is Required",
          "description": "Whether the attribute is required (must be true)"
        },
        "default_value": {
          "type": "string",
          "title": "Default Value",
          "description": "Default value for the attribute (must be '0')"
        }
      },
      "required": [
        "asset_type_id",
        "name",
        "data_type",
        "is_required",
        "default_value"
      ]
    }

Tool response:
Tool: list_custom_attributes_for_asset_type
Description: List Custom Attributes For Asset Type
Parameters:
    {
      "type": "object",
      "properties": {
        "asset_type_id": {
          "type": "integer",
          "description": "Internal ID of the asset type to retrieve custom attributes for",
          "title": "Asset Type Id"
        }
      },
      "required": [
        "asset_type_id"
      ]
    }
